CREATE SCHEMA IF NOT EXISTS agent_engine;
CREATE TABLE IF NOT EXISTS agent_engine.projects(id text PRIMARY KEY,name text NOT NULL,repository_url text,default_branch text NOT NULL DEFAULT 'main',rules jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_engine.agents(id text PRIMARY KEY,role text NOT NULL,display_name text NOT NULL,model text NOT NULL,enabled boolean NOT NULL DEFAULT true,configuration jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(role IN('backend','frontend','database','security','testing','code_review')));
CREATE TABLE IF NOT EXISTS agent_engine.tasks(id text PRIMARY KEY,project_id text NOT NULL REFERENCES agent_engine.projects(id) ON DELETE CASCADE,title text NOT NULL,description text NOT NULL,category text NOT NULL,execution_mode text NOT NULL DEFAULT 'approval',status text NOT NULL DEFAULT 'queued',requested_by text,input jsonb NOT NULL DEFAULT '{}'::jsonb,result jsonb,error_message text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,completed_at timestamptz,CHECK(execution_mode IN('approval','autonomous')),CHECK(status IN('queued','running','validating','awaiting_approval','ready_to_propose','proposed','failed','cancelled')));
CREATE INDEX IF NOT EXISTS tasks_project_created_idx ON agent_engine.tasks(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS tasks_status_created_idx ON agent_engine.tasks(status,created_at);
CREATE TABLE IF NOT EXISTS agent_engine.task_steps(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,agent_id text REFERENCES agent_engine.agents(id) ON DELETE SET NULL,step_order integer NOT NULL,status text NOT NULL DEFAULT 'queued',input jsonb NOT NULL DEFAULT '{}'::jsonb,output jsonb,error_message text,started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(task_id,step_order));
CREATE TABLE IF NOT EXISTS agent_engine.executions(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,agent_id text REFERENCES agent_engine.agents(id) ON DELETE SET NULL,provider text NOT NULL DEFAULT 'gemini',model text NOT NULL,status text NOT NULL,prompt_tokens integer,output_tokens integer,estimated_cost numeric(14,6),duration_ms integer,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_engine.artifacts(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,file_path text NOT NULL,operation text NOT NULL,content text NOT NULL,content_sha256 text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(operation IN('create','update','delete')));
CREATE TABLE IF NOT EXISTS agent_engine.validation_results(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,passed boolean NOT NULL,checks jsonb NOT NULL DEFAULT '[]'::jsonb,findings jsonb NOT NULL DEFAULT '[]'::jsonb,validator_version text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_engine.approvals(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,requested_by text,decided_by text,decision text NOT NULL DEFAULT 'pending',comment text,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,CHECK(decision IN('pending','approved','rejected')));
CREATE TABLE IF NOT EXISTS agent_engine.usage(id text PRIMARY KEY,task_id text NOT NULL REFERENCES agent_engine.tasks(id) ON DELETE CASCADE,execution_id text REFERENCES agent_engine.executions(id) ON DELETE SET NULL,provider text NOT NULL DEFAULT 'gemini',model text NOT NULL,input_tokens integer,output_tokens integer,estimated_cost numeric(14,6),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_engine.audit_logs(id text PRIMARY KEY,project_id text REFERENCES agent_engine.projects(id) ON DELETE SET NULL,task_id text REFERENCES agent_engine.tasks(id) ON DELETE SET NULL,actor_id text,action text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_project_created_idx ON agent_engine.audit_logs(project_id,created_at DESC);
